package cn.mop.api;

import cn.mop.domain.*;
import cn.mop.domain.assetimport.source.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Isolated request boundaries; mocks are not proof of designated component integration. */
class AssetImportControllerTest {
    static final String ACTOR="55000000-0000-4000-8000-000000000003",TENANT="55000000-0000-4000-8000-000000000001",SOURCE="55000000-0000-4000-8000-000000000009",OP="55000000-0000-4000-8000-000000000010";
    private PlatformRepository platform;private AssetImportSourceRepository sources;private AssetImportObjectStore store;private AssetImportController controller;private final ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);sources=mock(AssetImportSourceRepository.class);store=mock(AssetImportObjectStore.class);controller=new AssetImportController(platform,sources,store,new AssetImportPolicy(),mapper);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"tadmin",7,true)));when(sources.ready()).thenReturn(true);when(store.ready()).thenReturn(true);when(platform.idempotent(anyString(),anyString(),anyString(),anyString(),anyString(),anyLong(),any())).thenAnswer(call->call.getArgument(6,Supplier.class).get());when(sources.acceptSource(any(),anyString(),any(),any())).thenReturn(Map.of("source_id",SOURCE,"operation_id",OP,"status","PENDING"));}
    MockHttpServletRequest request(String method,String route){var request=new MockHttpServletRequest(method,"/api/v1"+route);var session=new MockHttpSession();session.setAttribute("mop.tenant_id",TENANT);request.setSession(session);request.setUserPrincipal(()->ACTOR);request.addHeader("Idempotency-Key","isolated-import-1");request.setAttribute("mop.trace_id","isolated-import");return request;}
    private MockHttpServletRequest upload(String name,byte[] bytes){var request=request("POST","/assets/import-sources");request.setContentType("multipart/form-data");var file=new MockPart("file",name,bytes);file.getHeaders().setContentType(org.springframework.http.MediaType.parseMediaType("text/csv"));request.addPart(file);request.addPart(new MockPart("purpose","asset_import_source".getBytes(StandardCharsets.UTF_8)));request.addPart(new MockPart("format","CSV".getBytes(StandardCharsets.UTF_8)));return request;}
    static String selection(){return "{\"expected_version\":2,\"declared_format\":\"CSV\",\"encoding\":\"UTF-8\",\"delimiter\":\",\",\"sheet_index\":null,\"header_row\":1}";}
    @Test void uploadPreservesOriginalBytesAndCanonicalReplayIgnoresMultipartBoundaryButBindsName() {
        byte[] original="设备名称,备注\r\n测试设备,虚构数据\r\n".getBytes(StandardCharsets.UTF_8);var first=upload("原始.csv",original);first.setContentType("multipart/form-data; boundary=one");assertEquals(202,controller.upload(first).getStatusCode().value());var second=upload("原始.csv",original);second.setContentType("multipart/form-data; boundary=two");controller.upload(second);controller.upload(upload("改名.csv",original));
        var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(3)).idempotent(eq(ACTOR),eq(TENANT),eq("/api/v1/assets/import-sources"),eq("isolated-import-1"),hashes.capture(),eq(7L),any());assertEquals(hashes.getAllValues().get(0),hashes.getAllValues().get(1));assertNotEquals(hashes.getAllValues().get(0),hashes.getAllValues().get(2));verify(sources,times(2)).acceptSource(new AssetImportSourceRepository.Access(ACTOR,TENANT,7,"isolated-import"),"原始.csv",ImportFormat.CSV,original);verify(store,never()).storeImmutable(anyString(),any(),any(),anyString());
    }
    @Test void extraDuplicateUnknownQueryMissingAndLargePartsNeverAdmit(){
        for(String name:List.of("file","purpose","format","tenant_id","actor_id")){var request=upload("a.csv",new byte[]{1});request.addPart(new MockPart(name,new byte[]{1}));assertEquals(400,assertThrows(DomainException.class,()->controller.upload(request)).status);}
        var query=upload("a.csv",new byte[]{1});query.setQueryString("tenant_id=forged");assertThrows(DomainException.class,()->controller.upload(query));
        assertThrows(DomainException.class,()->controller.upload(request("POST","/assets/import-sources")));var large=upload("a.csv",new byte[Math.toIntExact(ImportLimits.MAX_SOURCE_BYTES)+1]);assertThrows(DomainException.class,()->controller.upload(large));var noKey=upload("a.csv",new byte[]{1});noKey.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.upload(noKey));verify(sources,never()).acceptSource(any(),any(),any(),any());
    }
    @Test void failedStoreDoesNotAdmitNewSourceWhileDurableReplayBypassesProbe(){
        when(store.ready()).thenReturn(false);assertEquals(503,assertThrows(DomainException.class,()->controller.upload(upload("a.csv",new byte[]{1}))).status);verify(sources,never()).acceptSource(any(),any(),any(),any());reset(store,sources);doReturn(Map.of("source_id",SOURCE,"operation_id",OP,"status","PENDING")).when(platform).idempotent(anyString(),anyString(),anyString(),anyString(),anyString(),anyLong(),any());assertEquals(202,controller.upload(upload("a.csv",new byte[]{1})).getStatusCode().value());verifyNoInteractions(store,sources);
    }
    @Test void invalidFormatConfigurationRejectsNewAdmissionButKeepsRecordedReplay(){controller=new AssetImportController(platform,sources,store,new AssetImportPolicy(null),mapper);assertEquals(503,assertThrows(DomainException.class,()->controller.upload(upload("a.csv",new byte[]{1}))).status);verifyNoInteractions(store);verify(sources,never()).acceptSource(any(),any(),any(),any());doReturn(Map.of("source_id",SOURCE,"operation_id",OP,"status","PENDING")).when(platform).idempotent(anyString(),anyString(),anyString(),anyString(),anyString(),anyLong(),any());assertEquals(202,controller.upload(upload("a.csv",new byte[]{1})).getStatusCode().value());}
    @Test void viewerCannotUseReadOrWriteAndBrowserScopeIsNotTrusted(){
        when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"viewer",8,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.policy(request("GET","/assets/import-policy"))).status);assertEquals(403,assertThrows(DomainException.class,()->controller.source(SOURCE,request("GET","/assets/import-sources/"+SOURCE))).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.policy(request("GET","/assets/import-policy"))).status);var absent=request("GET","/assets/import-policy");absent.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.policy(absent)).status);verifyNoInteractions(sources,store);
    }
    @Test void parseIsExplicitFlatStrictAndCanonicalAcrossJsonPropertyOrder()throws Exception{
        when(sources.requestParse(any(),eq(SOURCE),eq(2L),any())).thenReturn(Map.of("source_id",SOURCE,"operation_id",OP,"status","PENDING"));JsonNode body=mapper.readTree(selection());assertEquals(202,controller.parse(SOURCE,body,request("POST","/assets/import-sources/"+SOURCE+"/parses")).getStatusCode().value());
        var reordered=mapper.createObjectNode();List<String> names=new ArrayList<>();body.fieldNames().forEachRemaining(names::add);Collections.reverse(names);names.forEach(name->reordered.set(name,body.get(name)));controller.parse(SOURCE,reordered,request("POST","/assets/import-sources/"+SOURCE+"/parses"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(2)).idempotent(anyString(),anyString(),anyString(),anyString(),hashes.capture(),eq(7L),any());assertEquals(hashes.getAllValues().get(0),hashes.getAllValues().get(1));
        for(String extra:List.of("tenant_id","actor_id","selection","unknown")){var malformed=body.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)malformed).put(extra,"forged");assertThrows(DomainException.class,()->controller.parse(SOURCE,malformed,request("POST","/assets/import-sources/"+SOURCE+"/parses")));}
        var fractional=(com.fasterxml.jackson.databind.node.ObjectNode)body.deepCopy();fractional.put("header_row",1.5);assertThrows(DomainException.class,()->controller.parse(SOURCE,fractional,request("POST","/assets/import-sources/"+SOURCE+"/parses")));
    }
    @Test void mappingRequiresAll15NoteAndUniqueExplicitSourceDisposition()throws Exception{
        var body=mapper.createObjectNode().put("expected_version",4).put("source_parse_hash","a".repeat(64));var targets=body.putObject("target_source_columns");for(var column:cn.mop.domain.assetimport.AssetImportPrechecker.Column.values())targets.putNull(column.name());targets.put("NOTE",1);body.putArray("ignored_source_columns").add(0);when(sources.saveMapping(any(),eq(SOURCE),any())).thenReturn(Map.of("id",SOURCE,"business_status","CONFIG_PENDING","can_import",false));controller.mapping(SOURCE,body,request("POST","/assets/import-sources/"+SOURCE+"/mappings"));verify(sources).saveMapping(eq(new AssetImportSourceRepository.Access(ACTOR,TENANT,7,"isolated-import")),eq(SOURCE),argThat(mapping->mapping.targetSourceColumns().size()==15&&mapping.ignoredSourceColumns().equals(Set.of(0))));
        targets.putNull("NOTE");assertThrows(DomainException.class,()->controller.mapping(SOURCE,body,request("POST","/assets/import-sources/"+SOURCE+"/mappings")));targets.put("NOTE",1);body.withArray("ignored_source_columns").add(0);assertThrows(DomainException.class,()->controller.mapping(SOURCE,body,request("POST","/assets/import-sources/"+SOURCE+"/mappings")));body.withArray("ignored_source_columns").removeAll();targets.put("NAME",1);assertThrows(DomainException.class,()->controller.mapping(SOURCE,body,request("POST","/assets/import-sources/"+SOURCE+"/mappings")));
    }
    @Test void sourceErrorsRemain404Or503AndReadAuditDoesNotCopyRawCells(){
        var access=new AssetImportSourceRepository.Access(ACTOR,TENANT,7,"isolated-import");when(sources.source(access,SOURCE)).thenThrow(new DomainException(404,"OBJECT_NOT_FOUND","对象不可见"));assertEquals(404,assertThrows(DomainException.class,()->controller.source(SOURCE,request("GET","/assets/import-sources/"+SOURCE))).status);doThrow(new DomainException(503,"UPSTREAM_UNAVAILABLE","指定源不可用")).when(sources).source(access,SOURCE);assertEquals(503,assertThrows(DomainException.class,()->controller.source(SOURCE,request("GET","/assets/import-sources/"+SOURCE))).status);doReturn(Map.of("id",SOURCE)).when(sources).source(access,SOURCE);controller.source(SOURCE,request("GET","/assets/import-sources/"+SOURCE));verify(platform).audit(ACTOR,TENANT,"asset.import.source.read","asset_import_source",SOURCE,"SUCCEEDED","CREATOR_ONLY_RAW_PREVIEW_CONFIG_PENDING","isolated-import");verifyNoInteractions(store);
    }
}
